mapper.select:
SELECT count(*)
FROM document_version
WHERE document_id=#{id}

SELECT DISTINCT object_key
FROM document_version
WHERE document_id=#{id}

mapper.update:
UPDATE document_cleanup_task
SET status=#{status},error_code=#{error},next_attempt_at=#{due}
WHERE id=#{task.id} AND status='RUNNING' AND attempt_count=#{task.attemptCount}

mapper.select:
SELECT version_no,name,source_format,sha256,size_bytes,status,created_at,updated_at
FROM document_version
WHERE document_id=#{id}
ORDER BY version_no DESC
LIMIT #{limit}
OFFSET #{offset}

SELECT COALESCE(max(version_no),0)+1
FROM document_version
WHERE document_id=#{id}

SELECT knowledge_base_id
FROM document
WHERE id=#{id}
